{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    segs = []
    for s in segments:
        segs.append({
            'name': s['name'],
            'importance': s['importance'],
            'min': s['minimum'],
            'cap': s['capacity'],
            'alloc': s['minimum']
        })
    total_min = sum(s['min'] for s in segs)
    total_cap = sum(s['cap'] for s in segs)
    if budget < total_min or budget > total_cap:
        raise ValueError("Budget out of bounds")
    total_alloc = total_min
    while total_alloc < budget:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segs):
            if s['alloc'] < s['cap']:
                next_pos = s['alloc'] + 1
                score = s['importance'] / next_pos
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        segs[best_idx]['alloc'] += 1
        total_alloc += 1
    allocations = [s['alloc'] for s in segs]
    by_name = {s['name']: s['alloc'] for s in segs}
    total = total_alloc
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
}
